Dressing:
```js
function showDressing() {
  state.screen='dressing';
  clearStageChars();
  // maybe show player char preview with current outfit
  updateDressingUI();
}
function updateDressingUI() {
  const cat = CATEGORIES.find(c=>c.key===state.selectedCategory);
  const opts = state.options[state.selectedCategory];
  const selectedId = state.playerOutfit[state.selectedCategory]?.id;
  ui.innerHTML = `
    <div class="overlay" style="align-items:flex-start;padding-top:20px">
      <div class="card dressing">
        <div class="round-info">
          <div>Runde ${state.round} / ${state.roundsTotal}</div>
          <div class="theme">${state.theme.title}</div>
        </div>
        <div class="categories">
          ${CATEGORIES.map(c=>`<button class="cat-btn ${c.key===state.selectedCategory?'active':''}" data-cat="${c.key}">${c.label}</button>`).join('')}
        </div>
        <div class="options">
          ${opts.map(o=>`
            <div class="option ${o.id===selectedId?'selected':''}" data-opt="${o.id}">
              <span class="swatch" style="background:${o.color}"></span>${o.name}
            </div>`).join('')}
        </div>
        <div style="margin-top:12px;display:flex;justify-content:space-between;align-items:center">
          <div style="opacity:.7">Gewählt: ${Object.keys(state.playerOutfit).length}/${CATEGORIES.length} Kategorien</div>
          <button id="runwayBtn">Auf den Laufsteg</button>
        </div>
      </div>
    </div>`;
  // handlers
  document.querySelectorAll('.cat-btn').forEach(b=>{
    b.onclick = ()=>{ state.selectedCategory=b.dataset.cat; updateDressingUI(); };
  });
  document.querySelectorAll('.option').forEach(el=>{
    el.onclick = ()=>{
      const id = el.dataset.opt;
      const opt = opts.find(o=>o.id===id);
      state.playerOutfit[state.selectedCategory] = opt;
      updateDressingUI();
      updatePreviewOutfit();
    };
  });
  document.getElementById('runwayBtn').onclick = ()=>{ startRunway(); };
  // preview char
  updatePreviewOutfit();
}
```

Preview char during dressing: We can render player character with current outfit at side/center? The stage canvas behind UI. We'll add a preview character to scene, rotating slowly, if not present. Manage `state.previewChar`.

```js
function ensurePreviewChar() {
  if (state.previewChar) return;
  clearStageChars();
  const ch = createCharacter(state.playerSpecies, state.playerOutfit);
  ch.position.set(0,0,0);
  scene.add(ch);
  state.previewChar = ch;
